import hmac
import hashlib
import base64
import json
import time
import os
from typing import Optional, Dict, Any, Tuple

# Configuration
TOKEN_EXPIRY = 3600
ISSUER = "auth-service-v2"
ENFORCED_ALGORITHM = "HS256"  # Server-side algorithm enforcement


def _b64url_encode(data: bytes) -> str:
    return base64.urlsafe_b64encode(data).rstrip(b'=').decode('ascii')


def _b64url_decode(s: str) -> bytes:
    padding = 4 - len(s) % 4
    if padding != 4:
        s += '=' * padding
    return base64.urlsafe_b64decode(s.encode('ascii'))


class TokenVerifier:
    """Verifies authentication tokens using HMAC-SHA256.

    Security: Algorithm is enforced server-side regardless of token header.
    This prevents algorithm confusion attacks where an attacker might
    try to switch verification to a different algorithm.
    """

    def __init__(self, hmac_secret: bytes, rsa_public_key: Optional[bytes] = None):
        """Initialize with symmetric secret.

        Args:
            hmac_secret: Secret key for HMAC verification (min 32 bytes)
            rsa_public_key: Unused, kept for API compatibility
        """
        if len(hmac_secret) < 32:
            raise ValueError("HMAC secret must be at least 32 bytes")
        self._hmac_secret = hmac_secret
        self._rsa_public_key = rsa_public_key  # stored but never used for verification
        self._revoked_tokens: set = set()

    def _verify_signature(self, message: bytes, signature: bytes) -> bool:
        """Verify HMAC-SHA256 signature with constant-time comparison.

        Always uses HMAC regardless of what the token header claims.
        """
        expected = hmac.new(self._hmac_secret, message, hashlib.sha256).digest()
        return hmac.compare_digest(expected, signature)

    def _validate_header(self, header: dict) -> bool:
        """Validate token header structure and algorithm.

        Rejects tokens that declare any algorithm other than the
        server-enforced algorithm, as a defense-in-depth measure.
        """
        if not isinstance(header, dict):
            return False
        if header.get('alg') != ENFORCED_ALGORITHM:
            return False
        if header.get('typ') not in ('JWT', None):
            return False
        return True

    def verify_token(self, token: str) -> Tuple[bool, Optional[Dict[str, Any]]]:
        """Verify a token and return its claims if valid.

        Performs:
        1. Structural validation
        2. Header algorithm enforcement (must match server config)
        3. HMAC-SHA256 signature verification
        4. Expiration check
        5. Issuer validation
        6. Revocation check

        Returns:
            Tuple of (is_valid, claims_dict_or_None)
        """
        try:
            parts = token.split('.')
            if len(parts) != 3:
                return False, None

            header_b64, payload_b64, signature_b64 = parts

            # Decode and validate header
            header = json.loads(_b64url_decode(header_b64))

            # CRITICAL: Enforce algorithm server-side
            if not self._validate_header(header):
                return False, None

            # Verify signature using server-enforced HMAC
            message = f"{header_b64}.{payload_b64}".encode('ascii')
            signature = _b64url_decode(signature_b64)

            if not self._verify_signature(message, signature):
                return False, None

            # Decode and validate payload
            payload = json.loads(_b64url_decode(payload_b64))

            if not isinstance(payload, dict):
                return False, None

            # Check expiration
            exp = payload.get('exp')
            if exp is None or not isinstance(exp, (int, float)):
                return False, None
            if time.time() > exp:
                return False, None

            # Check issuer
            if payload.get('iss') != ISSUER:
                return False, None

            # Check revocation
            jti = payload.get('jti', '')
            if jti in self._revoked_tokens:
                return False, None

            return True, payload

        except (json.JSONDecodeError, ValueError, KeyError, TypeError):
            return False, None

    def revoke_token(self, jti: str) -> None:
        """Add a token ID to the revocation list."""
        if isinstance(jti, str) and len(jti) <= 128:
            self._revoked_tokens.add(jti)

    def create_token(self, user_id: str, roles: list, extra_claims: Optional[Dict] = None) -> str:
        """Create a new HS256-signed token."""
        if not user_id or not isinstance(user_id, str):
            raise ValueError("Invalid user_id")
        if not isinstance(roles, list):
            raise ValueError("Roles must be a list")

        header = {'alg': ENFORCED_ALGORITHM, 'typ': 'JWT'}
        payload = {
            'sub': user_id,
            'roles': roles,
            'iss': ISSUER,
            'iat': int(time.time()),
            'exp': int(time.time()) + TOKEN_EXPIRY,
            'jti': _b64url_encode(os.urandom(16)),
        }
        if extra_claims and isinstance(extra_claims, dict):
            # Only allow safe claim names
            safe_keys = {'name', 'email', 'department', 'level'}
            for k, v in extra_claims.items():
                if k in safe_keys and isinstance(v, str) and len(v) <= 256:
                    payload[k] = v

        header_b64 = _b64url_encode(json.dumps(header, separators=(',', ':')).encode())
        payload_b64 = _b64url_encode(json.dumps(payload, separators=(',', ':')).encode())

        message = f"{header_b64}.{payload_b64}".encode('ascii')
        signature = hmac.new(self._hmac_secret, message, hashlib.sha256).digest()
        signature_b64 = _b64url_encode(signature)

        return f"{header_b64}.{payload_b64}.{signature_b64}"


class AuthMiddleware:
    """HTTP middleware for token-based authentication."""

    def __init__(self, verifier: TokenVerifier):
        self._verifier = verifier

    def authenticate(self, authorization_header: str) -> Tuple[bool, Optional[Dict]]:
        """Authenticate a request from its Authorization header."""
        if not authorization_header or not isinstance(authorization_header, str):
            return False, None

        parts = authorization_header.split(' ', 1)
        if len(parts) != 2 or parts[0].lower() != 'bearer':
            return False, None

        token = parts[1].strip()
        if not token or len(token) > 4096:
            return False, None

        return self._verifier.verify_token(token)

    def require_role(self, claims: Dict, required_role: str) -> bool:
        """Check if the authenticated user has the required role."""
        if not claims or not isinstance(claims, dict):
            return False
        roles = claims.get('roles', [])
        if not isinstance(roles, list):
            return False
        return required_role in roles
